"""Day 147 project: build artifacts (versioned data hash, trained MLP, ONNX export, golden outputs, calibrated drift threshold),
run the service's test-suite with pytest, load-test the running service, simulate drifted traffic, and write a model card from measured numbers."""
import os, sys, json, time, hashlib, subprocess, asyncio, numpy as np, torch, httpx, _mlops as M
HERE = os.path.dirname(os.path.abspath(__file__)); P = os.path.join(HERE, "project"); ART = os.path.join(P, "artifacts"); os.makedirs(ART, exist_ok=True)
Xtr, Xte, ytr, yte, names = M.data()
dh = hashlib.sha256(np.column_stack([Xtr, ytr]).astype(np.float64).tobytes()).hexdigest()[:12]
m = M.train(Xtr, ytr); acc = M.acc(m, Xte, yte); p = M.proba(m, Xte); th = 0.8   # threshold 0.8 = lowest cost on Day 141 (10:1 miss cost)
torch.onnx.export(m, (torch.zeros(1, 30),), os.path.join(ART, "model.onnx"), input_names=["x"], output_names=["logits"], dynamic_axes={"x": {0: "batch"}}, dynamo=False)
def psi(ref, cur, bins=10):
    e = np.unique(np.quantile(ref, np.linspace(0, 1, bins + 1))); e[0], e[-1] = -np.inf, np.inf
    r = np.histogram(ref, e)[0] / len(ref) + 1e-4; c = np.histogram(cur, e)[0] / len(cur) + 1e-4; return float(((c - r) * np.log(c / r)).sum())
rng = np.random.default_rng(0); W = len(Xte)
null = [max(psi(Xtr[:, k], Xtr[i, k]) for k in range(30)) for i in (rng.choice(len(Xtr), W) for _ in range(200))]
alert = float(np.percentile(null, 99)); print(f"data version {dh}; model {M.weights_hash(m)}; test acc {acc:.3f}; decision threshold {th}")
print(f"drift threshold calibrated on 200 no-drift windows of {W} rows from train: 99th pct of max-PSI over 30 features = {alert:.3f} (vs the 0.2 rule of thumb)")
json.dump({"weights_sha": M.weights_hash(m), "data_hash": dh, "n_features": 30, "features": names, "threshold": th, "psi_alert": alert, "min_window": 100, "test_acc": acc}, open(os.path.join(ART, "meta.json"), "w"))
np.save(os.path.join(ART, "reference.npy"), Xtr); np.save(os.path.join(ART, "golden_X.npy"), Xte)
json.dump({"weights_sha": M.weights_hash(m), "p": p.tolist(), "test_acc": acc}, open(os.path.join(ART, "golden.json"), "w"))
pred = p > th; fn = int((pred & (yte == 0)).sum()); fp = int((~pred & (yte == 1)).sum())
sl = np.digitize(Xte[:, names.index("mean area")], np.quantile(Xte[:, names.index("mean area")], [1/3, 2/3])); slices = {n: float(((p[sl == k] > th) == yte[sl == k]).mean()) for k, n in enumerate(["small", "medium", "large"])}
print(f"at threshold {th}: missed malignant {fn}, false alarms {fp}; acc by area tertile {json.dumps({k: round(v,3) for k,v in slices.items()})}")
print("== pytest")
r = subprocess.run([sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider", P], capture_output=True, text=True); print("  " + r.stdout.strip().splitlines()[-1])
print("== running service: load test + drifted traffic")
srv = subprocess.Popen([sys.executable, "-m", "uvicorn", "service:app", "--port", "8766", "--log-level", "warning"], cwd=P)
try:
    for _ in range(100):
        try: httpx.get("http://127.0.0.1:8766/health"); break
        except Exception: time.sleep(0.1)
    async def load(n=500, conc=8):
        lat = []
        async with httpx.AsyncClient(base_url="http://127.0.0.1:8766") as c:
            sem = asyncio.Semaphore(conc)
            async def one(i):
                async with sem:
                    t = time.perf_counter(); (await c.post("/predict", json={"rows": [Xte[i % W].tolist()]})).raise_for_status(); lat.append(time.perf_counter() - t)
            t0 = time.perf_counter(); await asyncio.gather(*[one(i) for i in range(n)]); return np.array(lat) * 1000, n / (time.perf_counter() - t0)
    l, rps = asyncio.run(load()); print(f"  500 single-row requests, concurrency 8: p50 {np.percentile(l,50):.1f} ms, p95 {np.percentile(l,95):.1f} ms, {rps:.0f} req/s; SLO p95<50 ms: {'met' if np.percentile(l,95)<50 else 'MISSED'}")
    print(f"  /metrics after clean traffic: {httpx.get('http://127.0.0.1:8766/metrics').json()}")
    Xd = Xte.copy(); Xd[:, [names.index(c) for c in names if "area" in c]] *= 1.3
    for i in range(0, 500, 50): httpx.post("http://127.0.0.1:8766/predict", json={"rows": Xd[np.arange(i, i + 50) % W].tolist()})
    print(f"  /metrics after 500 rows with area x1.3: {httpx.get('http://127.0.0.1:8766/metrics').json()}")
finally: srv.terminate(); srv.wait()
card = f"""# Model card: w21 breast-cancer MLP (course exercise, NOT for clinical use)
Generated by code/week-21/day147_project.py on this box; every number below is from that run.
- **Model:** MLP 30-32-32-2 (ReLU), normalisation inside the model; weights sha {M.weights_hash(m)}; ONNX export served with onnxruntime.
- **Data:** scikit-learn's bundled Wisconsin breast-cancer table (569 rows, 30 features); stratified 75/25 split, seed 0; train data hash {dh}.
- **Intended use:** teaching MLOps mechanics. Out of scope: any medical decision. The data are small, old and from one source.
- **Metrics (143 test rows):** accuracy {acc:.3f} at 0.5; at the deployed threshold {th}: missed malignant {fn}, false alarms {fp}. Accuracy by mean-area tertile: {', '.join(f'{k} {v:.3f}' for k,v in slices.items())}.
- **Uncertainty:** 143 test rows; one test error moves accuracy by {1/len(yte):.3f}.
- **Monitoring:** per-feature PSI on the last 500 inputs vs train; alert if max PSI > {alert:.3f} (99th pct of a no-drift calibration). Labels are not observed in production, so accuracy is not monitored.
- **Known limits:** drift alerts do not imply accuracy loss (Day 145); the drift threshold was calibrated on 143-row windows but the service uses a 500-row window (larger windows have less PSI noise, so the threshold is conservative); the Dockerfile and CI workflow are UNTESTED (no Docker on the box); a single training seed; load test ran client and server on one machine.
"""
open(os.path.join(P, "MODEL_CARD.md"), "w").write(card); print("model card written: code/week-21/project/MODEL_CARD.md")
